SELECT json_build_object('source_key',s.source_key,'publication_platform',s.source_name_ar,'configured_source_operator',s.organization_name,'source_type',s.source_type,'records',count(so.id),'linked_source_records',count(so.id) FILTER (WHERE so.master_opportunity_id IS NOT NULL),'linked_distinct_masters',count(DISTINCT so.master_opportunity_id) FILTER (WHERE o.merged_into_id IS NULL),'owner_projection_values',count(DISTINCT so.source_owner),'explicit_raw_publisher_records',count(so.id) FILTER (WHERE NULLIF(btrim(COALESCE(so.raw_data_json->>'publishing_entity',so.raw_data_json->>'publisher',so.raw_data_json->'attributes'->>'ENTITIESNAME','')),'') IS NOT NULL))::text
FROM sources s LEFT JOIN source_opportunities so ON so.source_id=s.id LEFT JOIN opportunities o ON o.id=so.master_opportunity_id
GROUP BY s.id,s.source_key,s.source_name_ar,s.organization_name,s.source_type,s.priority ORDER BY s.priority;
